<?php if($error): ?><div class="flash error" role="alert"><?= e($error) ?></div><?php endif; ?>
<div class="metrics"><div class="metric"><span><?= e(t('Total purchase amount')) ?></span><strong><?= e(money(array_sum(array_column($rows,'amount')))) ?> <small><?= e(t('MMK')) ?></small></strong><small><?= e(t('Selected duration')) ?></small></div><div class="metric"><span><?= e(t('Rice purchased')) ?></span><strong><?= e(num(array_sum(array_column($rows,'quantity')))) ?> <small><?= e(t('တင်း')) ?></small></strong><small><?= e(t('Selected warehouses')) ?></small></div><div class="metric"><span><?= e(t('Purchase count')) ?></span><strong><?= e(array_sum(array_column($rows,'purchases'))) ?></strong><small><?= e(t('Recorded purchases')) ?></small></div></div>
<section class="panel"><form method="get" class="filters report-filters" action="<?= e(url('reports')) ?>"><label><?= e(t('From date')) ?><input type="date" name="start" value="<?= e($start) ?>" required></label><label><?= e(t('To date')) ?><input type="date" name="end" value="<?= e($end) ?>" required></label><label><?= e(t('Warehouse')) ?><select name="warehouse"><option value="0"><?= e(t('All warehouses')) ?></option><?php foreach($warehouses as $w): ?><option value="<?= e($w['id']) ?>" <?= (int)$w['id']===$warehouse?'selected':'' ?>><?= e($w['name']) ?></option><?php endforeach; ?></select></label><label><?= e(t('Group by')) ?><select name="group"><?php foreach(['day'=>t('Day'),'month'=>t('Month'),'year'=>t('Year')] as $v=>$l): ?><option value="<?= $v ?>" <?= $v===$group?'selected':'' ?>><?= e(t($l)) ?></option><?php endforeach; ?></select></label><button class="button primary"><?= e(t('Update report')) ?></button><a class="button" href="<?= e(url('reports')) ?>"><?= e(t('Reset')) ?></a></form>
<div class="report-presets"><span class="muted"><?= e(t('Quick ranges:')) ?></span><?php foreach(['This month'=>[date('Y-m-01'),date('Y-m-t'),'day'],'This year'=>[date('Y-01-01'),date('Y-12-31'),'month'],'Last year'=>[(date('Y')-1).'-01-01',(date('Y')-1).'-12-31','month'],'By year'=>[(date('Y')-4).'-01-01',date('Y-12-31'),'year']] as $label=>$range): ?><a href="<?= e(url('reports').'?'.http_build_query(['start'=>$range[0],'end'=>$range[1],'group'=>$range[2],'warehouse'=>$warehouse])) ?>"><?= e(t($label)) ?></a><?php endforeach; ?></div>
<div class="panel-heading"><div><div class="eyebrow"><?= e(t('PURCHASE AMOUNTS · MMK')) ?></div><h2><?= e(t('Spending by')) ?> <?= e(t($group)) ?></h2></div><span class="muted"><?= e($start) ?> — <?= e($end) ?></span></div><div class="chart-container"><canvas id="purchase-chart" role="img" aria-label="<?= e(t('Purchase spending bar chart by {period}, in MMK',['period'=>t($group)])) ?>"></canvas></div><script id="chart-data" type="application/json"><?= json_encode($rows,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?></script><script src="<?= e(asset('vendor/chart.umd.min.js')) ?>" defer></script><?php if(!array_sum(array_column($rows,'purchases'))): ?><div class="panel-foot"><?= e(t('No purchases in this range. Try another date range or warehouse.')) ?></div><?php endif; ?></section>
<div class="dashboard-grid"><section class="panel"><div class="panel-heading"><h2><?= e(t('Period breakdown')) ?></h2></div><div class="table-wrap"><table><thead><tr><th><?= e(t('Period')) ?></th><th class="number"><?= e(t('Purchases')) ?></th><th class="number"><?= e(t('Quantity (တင်း)')) ?></th><th class="number"><?= e(t('Amount (MMK)')) ?></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['period']) ?></td><td class="number"><?= e($r['purchases']) ?></td><td class="number"><?= e(num($r['quantity'])) ?></td><td class="number"><?= e(money($r['amount'])) ?></td></tr><?php endforeach; ?></tbody></table></div></section><section class="panel"><div class="panel-heading"><h2><?= e(t('By warehouse')) ?></h2></div><div class="table-wrap"><table><thead><tr><th><?= e(t('Warehouse')) ?></th><th class="number"><?= e(t('Amount (MMK)')) ?></th></tr></thead><tbody><?php foreach($byWarehouse as $w): ?><tr><td><strong><?= e($w['name']) ?></strong><small><?= e($w['purchases']) ?> <?= e(t('purchases ·')) ?> <?= e(num($w['quantity'])) ?> <?= e(t('တင်း')) ?></small></td><td class="number"><?= e(money($w['amount'])) ?></td></tr><?php endforeach; ?><?php if(!$byWarehouse): ?><tr><td colspan="2" class="empty"><?= e(t('No purchases in this range.')) ?></td></tr><?php endif; ?></tbody></table></div></section></div>
